function beta_cr_fail(string $msg, int $code = 400): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]); exit();
}
// A reward id must look like a Twitch id and be synced for this channel (managed by Specter when $specter).
function beta_cr_reward(string $id, bool $specter = false): void {
    if (!preg_match('/^[A-Za-z0-9-]{1,64}$/', $id)) beta_cr_fail('Unknown reward.');
    require '/var/www/config/database.php';
    $bdb = new mysqli($db_servername, $db_username, $db_password, (string) ($_SESSION['username'] ?? ''));
    if ($bdb->connect_error) beta_cr_fail('Could not reach your rewards. Try again.', 500);
    $st = $bdb->prepare('SELECT managed_by FROM channel_point_rewards WHERE reward_id = ? LIMIT 1'); $st->bind_param('s', $id); $st->execute();
    $row = $st->get_result()->fetch_assoc(); $st->close(); $bdb->close();
    if (!$row) beta_cr_fail('That reward is not synced. Sync your rewards first.', 404);
    if ($specter && ($row['managed_by'] ?? '') !== 'specter') beta_cr_fail('Only rewards managed by Specter can do that. Use Manage first.', 409);
}
function beta_cr_fields(bool $edit): void {
    $p = fn($k) => (string) ($_POST[$k] ?? '');
    $t = trim($p('title'));
    if ($t === '' || mb_strlen($t) > 45 || preg_match('/[\x00-\x1F\x7F]/u', $t)) beta_cr_fail('Title must be 1 to 45 characters on one line.');
    if (!preg_match('/^\d{1,10}$/', $p('cost')) || (int) $p('cost') < 1 || (int) $p('cost') > 2147483647) beta_cr_fail('Cost must be a whole number of at least 1.');
    if (mb_strlen($p('prompt')) > 200 || preg_match('/[\x00-\x09\x0B\x0C\x0E-\x1F\x7F]/u', $p('prompt'))) beta_cr_fail('Description must be 200 characters or fewer.');
    if (isset($_POST['background_color']) && !preg_match('/^#[0-9A-Fa-f]{6}$/', $p('background_color'))) beta_cr_fail('Background colour must be a hex colour like #00E5CB.');
    foreach (['is_user_input_required', 'should_redemptions_skip_request_queue', 'is_max_per_stream_enabled', 'is_max_per_user_per_stream_enabled', 'is_global_cooldown_enabled', 'is_paused'] as $k)
        if (isset($_POST[$k]) && !in_array($p($k), ['true', 'false'], true)) beta_cr_fail('Invalid on/off value.');
    if (!$edit && isset($_POST['is_paused'])) beta_cr_fail('Unknown field.');
    foreach (['is_max_per_stream_enabled' => ['max_per_stream', 2147483647, 'Max per stream'], 'is_max_per_user_per_stream_enabled' => ['max_per_user_per_stream', 2147483647, 'Max per user'], 'is_global_cooldown_enabled' => ['global_cooldown_seconds', 604800, 'Global cooldown']] as $on => [$k, $hi, $l])
        if ($p($on) === 'true' && (!preg_match('/^\d{1,10}$/', $p($k)) || (int) $p($k) < 1 || (int) $p($k) > $hi)) beta_cr_fail("$l must be a whole number from 1 to $hi.");
}

